package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import htsjdk.tribble.readers.TabixReader;
import org.jlinalg.genetics.CaddCalibration;
import org.jlinalg.genetics.CaddVariantPreparation;
import org.jlinalg.genetics.VepVcf;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

/** Native CADD1.6 source components with complete immutable captures and explicit no-score outcomes. */
public final class CaddToolsCli {
    private CaddToolsCli(){ }
    static final String ACTION="Read WARNINGS.md and analysis-status.json before downstream use. SKIP3 (exit3): dependent analysis skipped; restore the named exact permitted input/resource or retain skip. FAIL2 (exit2): no complete result; preserve diagnostics, correct the named input/hash/index/schema/capacity cause and retry NEW output. An unmatched, omitted or nonfinite variant is unassessable; do not assign a benign/zero score or silently run another version/model. LOOKUP reads explicitly ordered, fully SHA256-bound local CADD1.6 score tables. All hits from the first matching table are retained. Literal chromosome names and alleles are never aliased. original-CADD1.6-preparation is an explicit option: uppercase and trim according to the original source, retaining original variants and a per-allele transformation ledger; it does not left-align or check the reference sequence. CALIBRATE maps supplied raw scores through the complete explicitly bound model/assembly-specific conversion table; it does not generate raw scores or certify the caller's table provenance. No prediction model, CADD-SV, dbNSFP/VEP plugin, downstream pathogenicity threshold, clinical classification or whole-paper reproduction is implemented by these components. Saved VERIFY checks capture integrity and recomputes every native ledger from retained inputs/query candidates, without external score files or executable tools. It does not independently authenticate upstream resources or re-query them. Capacities are checked bounds, not OS quotas. No data are submitted to a public API.";
    static final class Unavailable extends IOException{private static final long serialVersionUID=1L;Unavailable(String message){super(message);}}
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){Path root=null;boolean owned=false;Map<String,Object> summary=Map.of();
        try{
            if(args.length==1&&args[0].equals("--help")){out.println("cadd-tools --request JSON | --verify BUNDLE\nModes: LOOKUP and CALIBRATE. See docs/cadd-tools.md.\n"+ACTION);return 0;}
            if(args.length==2&&args[0].equals("--verify")){verify(Path.of(args[1]));out.println("Verified saved CADD source-component capture and recomputed every native ledger. "+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request JSON, --verify BUNDLE or --help");Path source=Path.of(args[1]).toAbsolutePath().normalize();byte[] bytes=NextflowFiles.bytes(source,2000000);var raw=object(SimpleJson.parse(NextflowFiles.utf8(bytes)),"request");root=resolve(source.getParent(),text(raw,"out"));Files.createDirectories(root.getParent());Files.createDirectory(root);owned=true;
            Files.write(root.resolve("source-request.json"),bytes,StandardOpenOption.CREATE_NEW);Files.createDirectory(root.resolve("inputs"));json(root.resolve("analysis-status.json"),Map.of("status","RUNNING","results_admitted",false));var r=CaddToolsRequest.validate(raw);var captured=new LinkedHashMap<String,Object>(raw);captured.put("out",".");String inputKey=text(r,"mode").equals("LOOKUP")?"input_vcf":"input_scores";String inputName=inputKey.equals("input_vcf")?"original.vcf":"raw-scores.tsv";Path input=resolve(source.getParent(),text(r,inputKey));CaddToolsFiles.copy(input,root.resolve("inputs/"+inputName),CaddToolsRequest.number(r,"maximum_input_bytes"));captured.put(inputKey,"inputs/"+inputName);var externalBefore=CaddToolsFiles.pin(input,CaddToolsRequest.number(r,"maximum_input_bytes"));json(root.resolve("source-bindings.json"),sources());
            if(text(r,"mode").equals("LOOKUP")){var tables=new ArrayList<Map<String,Object>>();for(Object value:list(r.get("score_tables"),"score_tables")){var t=new LinkedHashMap<String,Object>(object(value,"table"));for(String key:List.of("file","index"))t.put(key,resolve(source.getParent(),text(t,key)).toString());tables.add(t);}captured.put("score_tables",tables);}
            else{Path table=resolve(source.getParent(),text(r,"conversion_table"));CaddToolsFiles.copy(table,root.resolve("inputs/conversion-table.txt"),CaddToolsRequest.number(r,"maximum_resource_bytes"));if(!CaddToolsFiles.pin(table,CaddToolsRequest.number(r,"maximum_resource_bytes")).get("sha256").equals(r.get("conversion_sha256")))throw new IOException("Declared CADD conversion-table hash differs");captured.put("conversion_table","inputs/conversion-table.txt");}
            json(root.resolve("request.json"),captured);var effective=CaddToolsRequest.validate(captured);json(root.resolve("effective-request.json"),effective);
            if(text(r,"mode").equals("LOOKUP")){try(var original=new CaddToolsLookup.Original(root,effective)){json(root.resolve("score-resource-bindings.json"),Map.of("resources",original.bindings(),"authentication",false));summary=CaddToolsLookup.render(root,effective,original,false);original.verifyResources();}}
            else summary=CaddToolsCalibration.render(root,effective,false);
            if(!externalBefore.equals(CaddToolsFiles.pin(input,CaddToolsRequest.number(r,"maximum_input_bytes"))))throw new IOException("Original CADD input changed during analysis");json(root.resolve("result-summary.json"),summary);Files.writeString(root.resolve("WARNINGS.md"),warning(summary),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);capacity(root,effective);json(root.resolve("analysis-status.json"),Map.of("status","COMPLETE_SCOPED_CADD_COMPONENTS","results_admitted",true,"prediction_model_executed",false,"whole_paper_reproduced",false));CaddToolsFiles.seal(root);verify(root);out.println("Completed scoped CADD components: "+root);err.println("WARNINGS / REQUIRED ACTIONS: "+root.resolve("WARNINGS.md")+"\n"+ACTION);return 0;
        }catch(Exception|LinkageError|OutOfMemoryError failure){int code=failure instanceof Unavailable?3:2;String state=code==3?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RESULT";err.println(state+": "+failure+(owned&&root!=null?"\nWARNINGS / REQUIRED ACTIONS: "+root.resolve("WARNINGS.md"):"")+"\n"+ACTION);if(failure instanceof InterruptedIOException||failure instanceof InterruptedException)Thread.currentThread().interrupt();if(owned&&root!=null)try{json(root.resolve("analysis-status.json"),Map.of("status",state,"results_admitted",false,"cause",failure.toString(),"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"# "+state+"\n\nCAUSE: "+failure+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8);try(var trace=new PrintWriter(Files.newBufferedWriter(root.resolve("failure-stack.txt"),StandardCharsets.UTF_8))){failure.printStackTrace(trace);}CaddToolsFiles.seal(root);}catch(IOException e){err.println("Could not seal CADD failure diagnostics: "+e+"; retain output directory");}return code;}
    }
    static void verify(Path supplied)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();var saved=read(root.resolve("capture-files.json"),268435456);keys(saved,Set.of("schema_version","authentication","files"));if(integer(saved,"schema_version",0,1,1)!=1||!Boolean.FALSE.equals(saved.get("authentication")))throw new IOException("Invalid CADD integrity seal");var files=CaddToolsFiles.hashes(root);files.remove("capture-files.json");if(!same(files,saved.get("files")))throw new IOException("Saved CADD capture population or bytes changed");var state=read(root.resolve("analysis-status.json"));if(!Boolean.TRUE.equals(state.get("results_admitted"))||!"COMPLETE_SCOPED_CADD_COMPONENTS".equals(state.get("status"))||!Boolean.FALSE.equals(state.get("prediction_model_executed"))||!Boolean.FALSE.equals(state.get("whole_paper_reproduced")))throw new IOException("Failed/skipped CADD capture is not a complete source-component result");
        var captured=read(root.resolve("request.json"));var r=CaddToolsRequest.validate(captured);if(!".".equals(captured.get("out"))||!same(r,read(root.resolve("effective-request.json")))||!same(sources(),read(root.resolve("source-bindings.json"))))throw new IOException("Saved effective CADD request or producer source changed");var raw=read(root.resolve("source-request.json"));CaddToolsRequest.validate(raw);var expected=new LinkedHashMap<String,Object>(raw);expected.put("out",".");String mode=text(r,"mode");if(mode.equals("LOOKUP")){expected.put("input_vcf","inputs/original.vcf");var original=list(raw.get("score_tables"),"tables");var current=list(captured.get("score_tables"),"tables");if(original.size()!=current.size())throw new IOException("CADD captured table population differs");for(int i=0;i<original.size();i++){var t=new LinkedHashMap<String,Object>(object(original.get(i),"table"));var c=object(current.get(i),"table");t.put("file",c.get("file"));t.put("index",c.get("index"));if(!same(t,c))throw new IOException("CADD original table ID/hash differs");}expected.put("score_tables",current);}else{expected.put("input_scores","inputs/raw-scores.tsv");expected.put("conversion_table","inputs/conversion-table.txt");}if(!same(expected,captured))throw new IOException("Original/captured CADD scientific options differ");
        Map<String,Object> summary;if(mode.equals("LOOKUP")){try(var replay=new CaddToolsLookup.Replay(root,r)){summary=CaddToolsLookup.render(root,r,replay,true);}}else summary=CaddToolsCalibration.render(root,r,true);if(!same(summary,read(root.resolve("result-summary.json")))||!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warning(summary)))throw new IOException("Saved CADD summaries/warnings differ");capacity(root,r);
    }
    private static String warning(Map<String,Object> summary)throws IOException{return "# WARNINGS AND REQUIRED ACTIONS\n\n"+ACTION+"\n\nComplete scoped-component counts (no prediction model executed):\n\n```json\n"+NextflowJson.json(summary)+"\n```\n";}
    private static void capacity(Path root,Map<String,Object> r)throws IOException {long n=0;for(String name:List.of("results","lookup-capture.jsonl")){Path p=root.resolve(name);if(!Files.exists(p))continue;if(Files.isDirectory(p)){try(var paths=Files.walk(p)){for(Path f:paths.filter(Files::isRegularFile).toList()){n=Math.addExact(n,Files.size(f));if(n>CaddToolsRequest.number(r,"maximum_output_bytes"))throw new IOException("Complete CADD output plus query-capture capacity exceeded");}}}else{n=Math.addExact(n,Files.size(p));if(n>CaddToolsRequest.number(r,"maximum_output_bytes"))throw new IOException("Complete CADD output plus query-capture capacity exceeded");}}}
    private static Map<String,Object> sources()throws IOException {
        var classes=List.<Class<?>>of(CaddToolsCli.class,CaddToolsRequest.class,CaddToolsFiles.class,CaddToolsLookup.class,CaddToolsCalibration.class,CaddCalibration.class,CaddVariantPreparation.class,VepVcf.class,SeuratDifferentialContracts.class,SimpleJson.class,RsemJson.class,NextflowFiles.class,NextflowJson.class,NextflowParameters.class,TabixReader.class);
        var origins=new TreeMap<String,Object>();Set<Class<?>> seen=new HashSet<>();for(Class<?> type:classes)source(type,seen,origins);var paths=new TreeSet<Path>();for(Class<?> type:classes)try{Path path=Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI()).toAbsolutePath().normalize();if(Files.isRegularFile(path))paths.add(path);}catch(java.net.URISyntaxException e){throw new IOException("Invalid CADD producer container",e);}var containers=new TreeSet<String>();for(Path path:paths)containers.add(NextflowJson.json(CaddToolsFiles.pin(path,1000000000L)));return Map.of("schema_version",1,"authentication",false,"classes",origins,"complete_jar_containers",List.copyOf(containers));
    }
    private static void source(Class<?> type,Set<Class<?>> seen,Map<String,Object> origins)throws IOException {if(!seen.add(type))return;String name=type.getName().replace('.','/')+".class";try(var stream=type.getResourceAsStream("/"+name)){if(stream==null)throw new IOException("CADD producer class unavailable");byte[] bytes=stream.readAllBytes();origins.put(name,Map.of("bytes",bytes.length,"sha256",NextflowFiles.sha(bytes)));}for(Class<?> nested:type.getDeclaredClasses())source(nested,seen,origins);}
}
